                     (block 
                          (WASetValue #this OppArm (add 1 (WAGetValue #this OppArm)))
                          (sett BodyPart "arm")
                          (sett Intensity (WAGetValue #this OppArm))
                          (WADrawPage #this)
                          (sett DrawingCards 1)
                     )
