                (if ((greater-eq (WAGetSubmissionDamage Opp Back) (multiply 7 (WAGetValue #this OppBack)))
                     (block 
                          (WASetValue #this OppBack (add 1 (WAGetValue #this OppBack)))
                          (sett BodyPart "back")
                          (sett Intensity (WAGetValue #this OppBack))
                          (WADrawPage #this)
                          (sett DrawingCards 1)
                     )
                    )
                )
                (if ((greater-eq (WAGetSubmissionDamage Opp Head) (multiply 7 (WAGetValue #this OppHead)))
                     (block 
                          (WASetValue #this OppHead (add 1 (WAGetValue #this OppHead)))
                          (sett BodyPart "head")
                          (sett Intensity (WAGetValue #this OppHead))
                          (WADrawPage #this)
                          (sett DrawingCards 1)
