          (sett Index (WAGetHandCount #target))
          (loop (greater Index 0)
                (block 
                     (sett TheCard (item (WAGetHand #target) Index))
                     (sett Index (subtract Index 1))
                     (if ((and (WAIsMove TheCard)
                               (or (eq (WAStringGetValue TheCard Method) "Agility")
                                   (eq (WAStringGetValue TheCard Method) "Strength")
                               )
                          )
                          (block 
                               (WAMessage (WAGetOwner #target) (WAGetName #this) "has forced you to ditch" (WAGetName TheCard))
                               (WADitchPage #target Index)
                          )
                         )
                     )
                )
          )
     )
    )
)
